const [N, M] = readline().split(' ').map(Number);
const parcels = readline().split(' ').map(Number);
const order = readline().split(' ').map(Number);

// Position de chaque colis sur le carrousel.
const positions: number[] = new Array(N + 1);
for (let i = 0; i < N; i++) {
    positions[parcels[i]] = i;
}

let currentPosition = 0;
let direction = 1;
let totalMoves = 0;

for (let i = 0; i < M; i++) {
    const targetPosition = positions[order[i]];

    const distance = direction === 1
        ? (targetPosition - currentPosition + N) % N
        : (currentPosition - targetPosition + N) % N;

    totalMoves += distance;
    currentPosition = targetPosition;

    // Inverser même si la collecte n'a demandé aucun déplacement.
    direction *= -1;
}

console.log(totalMoves);
